messages.content:
Tool response:
Tool: create_invoice
Description: Create Invoice
Parameters:
    {
      "type": "object",
      "properties": {
        "visit_id": {
          "type": "integer",
          "title": "Visit Id"
        },
        "service_codes": {
          "items": {
            "properties": {
              "service_code_id": {
                "type": "integer",
                "title": "Service Code Id"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity",
                "default": 1
              }
            },
            "type": "object",
            "required": [
              "service_code_id"
            ],
            "title": "ServiceCodeItem"
          },
          "type": "array",
          "title": "Service Codes"
        },
        "discount_percent": {
          "type": "number",
          "title": "Discount Percent",
          "default": 0.0
        }
      },
      "required": [
        "visit_id",
        "service_codes"
      ]
    }

Tool response:
Tool: record_payment
Description: Record Payment
Parameters:
    {
      "type": "object",
      "properties": {
        "invoice_id": {
          "type": "integer",
          "title": "Invoice Id"
        },
        "amount": {
          "type": "number",
          "title": "Amount"
        },
        "payment_method": {
          "type": "string",
          "title": "Payment Method"
        },
        "payment_date": {
          "type": "string",
          "format": "date",
          "title": "Payment Date"
        }
      },
      "required": [
        "invoice_id",
        "amount",
        "payment_method",
        "payment_date"
      ]
    }
